    ($SATQ$c7a187a7$SATQ$, $SATQ$ccdb450a-31b3-42ec-9532-4859dd3972c3$SATQ$::uuid, $SATQ$e6e580f0-eb6a-4673-bfea-15ffe49bd41f$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 2, $SATQ$Math$SATQ$, $SATQ$Advanced Math$SATQ$, $SATQ$P$SATQ$, $SATQ$P.C.$SATQ$, $SATQ$Nonlinear functions$SATQ$, $SATQ$M$SATQ$, 5, $SATQ$mcq$SATQ$, NULL, $SATQ$<p style="text-align: center;"><math alttext="f left parenthesis x right parenthesis equals x squared minus 18 x minus 360"><mi>f</mi><mfenced><mi>x</mi></mfenced><mo>=</mo><mrow>
