/mi></math> is <math xmlns="http://www.w3.org/1998/Math/MathML" alttext="negative 8"><mo>-</mo><mn>8</mn></math>.</p>
<p style="text-align: left;">Choice B is incorrect. This may result from adding <math xmlns="http://www.w3.org/1998/Math/MathML" alttext="minus 5 x squared"><mo>-</mo><mn>5</mn><msup><mi>x</mi><mn>2</mn></msup></math> and <math xmlns="http://www.w3.org/1998/Math/MathML" alttext="3 x squared"><mn>3</mn><msup><mi>x</mi><mn>2</mn></msup></math>&nbsp;rather than <math xmlns="http://www.w3.org/1998/Math/MathML" alttext="minus 5 x squared"><mo>-</mo><mn>5</mn><msup><mi>x</mi><mn>2</mn></msup></math> and <math xmlns="http://www.w3.org/1998/Math/MathML" alttext="minus 3 x squared"><mo>-</mo><mn>3</mn><msup><mi>x</mi><mn>2</mn></msup></math>.</p>
<p style="text-align: left;">Choice C is incorrect. This may result from adding <math xmlns="http://www.w3.org/1998/Math/MathML" alttext="5 x squared"><mn>5</mn><msup><mi>x</mi><mn>2</mn></msup></math> and <math xmlns="http://www.w3.org/1998/Math/MathML" alttext="minus 3 x squared"><mo>-</mo><mn>3</mn><msup><mi>x</mi><mn>2</mn></msup></math>&nbsp;rather than <math xmlns="http://www.w3.org/1998/Math/MathML" alttext="minus 5 x squared"><mo>-</mo><mn>5</mn><msup><mi>x</mi><mn>2</mn></msup></math> and <math xmlns="http://www.w3.org/1998/Math/MathML" alttext="minus 3 x squared"><mo>-</mo><mn>3</mn><msup><mi>x</mi><mn>2</mn></msup></math>.</p>
<p style="text-align: left;">Choice D is incorrect. This may result from adding <math xmlns="http://www.w3.org/1998/Math/MathML" alttext="5 x squared"><mn>5</mn><msup><mi>x</mi><mn>2</mn></msup></math> and <math xmlns="http://www.w3.org/1998/Math/MathML" alttext="3 x squared"><mn>3</mn><msup><mi>x</mi><mn>2</mn></msup></math>&nbsp;rather than <math xmlns="http://www.w3.org/1998/Math/MathML" alttext="minus 5 x squared"><mo>-</mo><mn>5</mn><msup><mi>x</mi><mn>2</mn></msup></math> and <math xmlns="http://www.w3.org/1998/Math/MathML" alttext="minus 3 x squared"><mo>-</mo><mn>3</mn><msup><mi>x</mi><mn>2</mn></msup></math>.</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"c8a5c221","external_id":"902558e4-018d-442f-a571-ef4e6c7c9fae","disclosed_item_id":null,"source":"qbank","vaultid":null,"uId":"b6f5811b-0527-401b-b9ee-11a0cf8cd5bd","program":"SAT","test_type":2,"test_type_desc":"Math","primary_class_cd":"P","domain":"Advanced Math","skill_cd":"P.A.","skill_desc":"Equivalent expressions","difficulty":"H","score_band_range_cd":6,"type":"mcq","stimulus":null,"stem":"<p style=\"text-align: center;\"><math alttext=\"left parenthesis 9 x Superscript 4 Baseline plus 8 x cubed right parenthesis minus left parenthesis 7 x cubed plus 5 x squared right parenthesis minus left parenthesis 3 x squared plus x right parenthesis\"><mfenced><mrow><mn>9</mn><msup><mi>x</mi><mn>4</mn></msup><mo>+</mo><mn>8</mn><msup><mi>x</mi><mn>3</mn></msup></mrow></mfenced><mo>-</mo><mfenced><mrow><mn>7</mn><msup><mi>x</mi><mn>3</mn></msup><mo>+</mo><mn>5</mn><msup><mi>x</mi><mn>2</mn></msup></mrow></mfenced><mo>-</mo><mfenced><mrow><mn>3</mn><msup><mi>x</mi><mn>2</mn></msup><mo>+</mo><mi>x</mi></mrow></mfenced></math></p>\n<p style=\"text-align: left;\">The given expression can be written in the form <math alttext=\"9 x Superscript 4 plus x cubed plus a x squared minus x\"><mn>9</mn><msup><mi>x</mi><mn>4</mn></msup><mo>+</mo><msup><mi>x</mi><mn>3</mn></msup><mo>