    ($SATQ$c8bf5313$SATQ$, $SATQ$e223b909-79a8-46de-a366-14993592a4c7$SATQ$::uuid, $SATQ$494bf486-7d2c-43d2-a85a-a6d366320ac3$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 2, $SATQ$Math$SATQ$, $SATQ$Advanced Math$SATQ$, $SATQ$P$SATQ$, $SATQ$P.B.$SATQ$, $SATQ$Nonlinear equations in one variable and systems of equations in two variables $SATQ$, $SATQ$E$SATQ$, 3, $SATQ$mcq$SATQ$, NULL, $SATQ$<p style="text-align: center;"><math alttext="x equals 8"><mrow>
	<mi>x</mi>
	<mo>=</mo>
	<mn>8</mn>
</mrow>
</math></p>
