9 203.992079 \nL 115.917611 208.407805 \nL 117.231683 213.763047 \nL 118.282941 218.943932 \nL 119.334199 225.187564 \nL 120.385457 232.858311 \nL 121.436714 242.508605 \nL 122.225158 251.555756 \nL 122.487972 255.018246 \nL 122.487972 255.018246 \n\" style=\"fill:none;stroke:#000000;stroke-linecap:square;stroke-width:2.3;\"></path>\n   </g>\n   <g id=\"line2d_3\">\n    <path clip-path=\"url(#pdef97e787f)\" d=\"M 135.260754 36.88138 \nL 136.206886 54.193829 \nL 137.153018 67.178167 \nL 138.09915 77.277096 \nL 139.045282 85.356239 \nL 140.306792 93.910626 \nL 141.568301 100.664089 \nL 142.82981 106.131179 \nL 144.09132 110.64747 \nL 145.352829 114.441154 \nL 146.929716 118.407279 \nL 148.506602 121.712383 \nL 150.083489 124.50901 \nL 151.660376 126.906118 \nL 153.55264 129.366308 \nL 155.444904 131.466471 \nL 157.652545 133.558767 \nL 159.860186 135.345937 \nL 162.383205 137.093829 \nL 165.221601 138.76438 \nL 168.375374 140.333823 \nL 171.844525 141.789657 \nL 175.629053 143.127646 \nL 180.044336 144.434974 \nL 184.774996 145.603564 \nL 190.451788 146.766099 \nL 196.759335 147.82736 \nL 204.328391 148.864441 \nL 213.158956 149.836948 \nL 223.566408 150.748499 \nL 235.866124 151.595624 \nL 250.688859 152.38788 \nL 252.581123 152.475275 \nL 252.581123 152.475275 \n\" style=\"fill:none;stroke:#000000;stroke-linecap:square;stroke-width:2.3;\"></path>\n   </g>\n  </g>\n </g>\n <defs>\n  <clipPath id=\"pdef97e787f\">\n   <rect height=\"260.82\" width=\"268.898496\" x=\"7.2\" y=\"7.2\"></rect>\n  </clipPath>\n </defs>\n</svg>\n<div role=\"region\" aria-label=\"Long description for graph of 2 curves\" class=\"sr-only\"><ul><li>For the first curve:<br>\n<ul>\n<li>Moving from left to right, the curve is in quadrant 3.</li>\n<li>As x decreases, the curve approaches the line y equals negative 1.</li>\n<li>As x increases, the curve approaches the line x equals negative 1.</li>\n</ul>\n</li>\n<li>For the second curve:<br>\n<ul>\n<li>Moving from left to right, the curve passes from quadrant 2 to quadrant 1 to quadrant 4.</li>\n<li>As x decreases, the curve approaches the line x equals negative 1.</li>\n<li>As x increases, the curve approaches the line y equals negative 1.</li>\n</ul>\n</li>\n<li>The 2 curves pass through the following points:<br>\n<ul>\n<li>(negative 6 comma negative nine fifths)</li>\n<li>(0 comma 3)</li>\n<li>(4 comma negative one fifth)</li>\n</ul>\n</li>\n</ul></div></figure></p>\n<p style=\"text-align: left;\">What is the <em>y</em>-coordinate of the <em>y</em>-intercept of the graph shown?</p>","answerOptions":[],"keys":["3"],"correct_answer":["3"],"rationale":"<p style=\"text-align: left;\">The correct answer is <math alttext=\"3\"><mn>3</mn>\n</math>. A <em>y</em>-intercept of a graph in the <em>xy</em>-plane is a point <math alttext=\"left parenthesis x comma y right parenthesis\"><mfenced><mrow><mi>x</mi><mo>,</mo><mi>y</mi></mrow></mfenced></math> on the graph where <math alttext=\"x equals 0\"><mrow>\n\t<mi>x</mi>\n\t<mo>=</mo>\n\t<mn>0</mn>\n</mrow>\n</math>. For the graph shown, at <math alttext=\"x equals 0\"><mrow>\n\t<mi>x</mi>\n\t<mo>=</mo>\n\t<mn>0</mn>\n</mrow>\n</math>, the corresponding value of <math alttext=\"y\"><mi>y</mi>\n</math> is <math alttext=\"3\"><mn>3</mn>\n</math>. Therefore, the <em>y</em>-coordinate of the <em>y</em>-intercept of the graph shown is <math alttext=\"3\"><mn>3</mn>\n</math>.</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"image_count":0,"raw_list":{"updateDate":1730147357400,"pPcc":"SAT#P","questionId":"c99d154a","skill_cd":"P.C.","score_band_range_cd":3,"skill_desc":"Nonlinear functions","createDate":1730147357400,"program":"SAT","primary_class_cd_desc":"Advanced Math","ibn":"","external_id":"6f8b1a0e-8c22-4208-8038-796a6de480d4","primary_class_cd":"P","uId":"a6fb9f3f-b620-429a-bc6d-35ef3c3e5e4b","difficulty":"E"},"raw_detail":{"answerOptions":[],"externalid":"6f8b1a0e-8c22-4208-8038-796a6de480d4","keys":["3"],"rationale":"<p style=\"text-align: left;\">The correct answer is <math alttext=\"3\"><mn>3</mn>\n</math>. A <em>y</em>-intercept of a graph in the <em>xy</em>-plane is a point <math alttext=\"left parenthesis x comma y right parenthesis\"><mfenced><mrow><mi>x</mi><mo>,</mo><mi>y</mi></mrow></mfenced></math> on the graph where <math alttext=\"x equals 0\"><mrow>\n\t<mi>x</mi>\n\t<mo>=</mo>\n\t<mn>0</mn>\n</mrow>\n</math>. For the graph shown, at <math alttext=\"x equals 0\"><mrow>\n\t<mi>x</mi>\n\t<mo>=</mo>\n\t<mn>0</mn>\n</mrow>\n</math>, the corresponding value of <math alttext=\"y\"><mi>y</mi>\n</math> is <math alttext=\"3\"><mn>3</mn>\n</math>. Therefore, the <em>y</em>-coordinate of the <em>y</em>-intercept of the graph shown is <math alttext=\"3\"><mn>3</mn>\n</math>.</p>","stem":"<p style=\"text-align: center;\"><figure class='image'><svg height=\"275.22pt\" version=\"1.1\" viewBox=\"0 0 287.764248 275.22\" width=\"287.764248pt\" xmlns=\"http://www.w3.org/2000/svg\" xmlns:xlink=\"http://www.w3.org/1999/xlink\" role=\"img\" aria-label=\"Graph of 2 curves in the x y plane with the origin labeled O. The x axis ranges from negative 8 to 8. The y axis ranges from negative 8 to 8. Refer to long description.\">\n <defs>\n  <style type=\"text/css\">\n*{stroke-linecap:butt;stroke-linejoin:round;}\n  </style>\n </defs>\n <g id=\"figure_1\">\n  <g id=\"patch_1\">\n   <path d=\"M -0 275.22 \nL 287.764248 275.22 \nL 287.764248 0 \nL -0 0 \nz\n\" style=\"fill:none;\"></path>\n  </g>\n  <g id=\"axes_1\">\n   <g id=\"patch_2\">\n    <path d=\"M 8.404248 260.46 \nL 280.564248 260.46 \nL 280.564248 10.98 \nL 8.404248 10.98 \nz\n\" style=\"fill:none;\"></path>\n   </g>\n   <g id=\"matplotlib.axis_1\"></g>\n   <g id=\"matplotlib.axis_2\"></g>\n  </g>\n  <g id=\"axes_2\">\n   <g id=\"patch_3\">\n    <path d=\"M 7.2 268.02 \nL 276.098496 268.02 \nL 276.098496 7.2 \nL 7.2 7.2 \nz\n\" style=\"fill:none;\"></path>\n   </g>\n   <g id=\"matplotlib.axis_3\">\n